INSERT INTO `quiz_question` VALUES (1,'पूरी दुनिया में कितने देश हैं ?','','195','125#HAS198#HAS211',1,'Publish',2665,'2024-10-19 13:42:13'),(2,'दुनिया में सबसे खुशहाल देश कौन सा है ?','','फिनलैंड','अमेरिका#HASजर्मनी#HASन्यूजीलैंड',1,'Publish',107,'2024-10-19 13:42:13'),(3,'पूरी दुनिया में पीने लायक पानी सबसे अधिक किस देश में है ?','','ब्राजील','चीन#HASथाईलैंड#HASभारत',1,'Publish',107,'2024-10-19 13:42:13'),(4,'दुनिया में सबसे ज्यादा युद्ध में भाग लेने वाला देश कौन सा है ?','','इंग्लैंड','चीन#HASजर्मनी#HASरूस',1,'Publish',108,'2024-10-19 13:42:13'),(5,'नंद लाल बोस, मंजीत बावा, तैयब मेहता ये सभी इनमे से क्या हैं ?','','चित्रकारों','अंग्रेजी कवि#HASफोटोग्राफर#HASशास्त्रीय गायक',1,'Publish',107,'2024-10-19 13:42:13'),(6,'मधुबनी ‘लोक चित्रों की एक शैली है, जो भारत के किस राज्य में सबसे अधिक प्रसिद्ध है ?','','राजस्थान','पश्चिम बंगाल#HASबिहार#HASमध्य प्रदेश',1,'Publish',29314,'2024-10-19 13:48:44'),(7,'निम्नलिखित में से कौन एक चित्रकार नहीं है ?','','रामकिंकर बैज','जैमिनी रॉय#HASतैयब मेहता#HASसैयद हैदर रज़ा',1,'Publish',107,'2024-10-19 13:48:44'),(8,'भारतीय सांस्कृतिक संबंध परिषद की स्थापना किसके द्वारा की गई थी ?','','मौलाना अबुल कलाम आज़ाद','इंदिरा गांधी#HASराजगोपालाचारी#HASसरदार वल्लभभाई पटेल',1,'Publish',236,'2024-10-19 13:48:44'),(9,'इनमे से कौन एक प्रतिष्ठित अभिनेता होने के साथ-साथ ज्ञानपीठ पुरस्कार (भारत में सर्वोच्च साहित्यिक पुरस्कार) का प्राप्तकर्ता है ?','','गिरीश कर्नाड','कैफ़ी आज़मी#HASजावेद अख्तर#HASविजय तेंदुलकर',1,'Publish',229,'2024-10-19 13:48:44'),(10,'यवनिका या पर्दा भारतीय रंगमंच पर इनमे से किसके द्वारा प्रस्तुत किया गया था ?','','यूनानियों','फारसियों#HASशक#HASहंस',1,'Publish',229,'2024-10-19 13:48:44'),(11,'राजा हरिश्चंद्र फिल्म को किस भारतीय फिल्म द्वारा निर्मित किया गया था ?','','दादा साहेब फाल्के','अर्देशिर ईरानी#HASअशोक कुमार#HASगुरुदात',1,'Publish',229,'2024-10-19 13:48:44'),(12,'प्रसिद्ध चित्रकार “विन्सेंट विलेम वैन गो” किस देश के थे ?','','नीदरलैंड्स','इटली#HASफ्रांस#HASस्पेन',1,'Publish',107,'2024-10-19 13:48:44'),(13,'जवाहरलाल नेहरु बंदरगाह