  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_src` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `biography` text COLLATE utf8mb4_unicode_ci,
  `password` text COLLATE utf8mb4_unicode_ci,
  `timestamp` datetime DEFAULT NULL,
  `tokena` text COLLATE utf8mb4_unicode_ci,
  `tokenx` text COLLATE utf8mb4_unicode_ci,
  `ipinfo` text COLLATE utf8mb4_unicode_ci,
  `device` text COLLATE utf8mb4_unicode_ci,
  `active` int DEFAULT NULL,
  `gender` int DEFAULT NULL,
  `reg_no` int DEFAULT NULL,
  `loginfo` mediumtext COLLATE utf8mb4_unicode_ci,
  `status` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=62352130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
